files.manifest.json:
{
  "name": "compare_currencies_to_czk_cnb",
  "kind": "workflow",
  "description": "Converts a list of foreign currencies to CZK using the CNB daily rate and ranks them by CZK value per unit, naming the strongest.",
  "signature": {
    "in": "{\"type\":\"object\",\"properties\":{\"currencies\":{\"type\":\"array\",\"items\":{\"type\":\"string\"}},\"amount\":{\"type\":\"number\"}},\"required\":[\"currencies\"]}",
    "out": "output of s2"
  },
  "steps": [
    {
      "id": "s1",
      "uses": "convert_to_czk_cnb_rate",
      "foreach": "$input.currencies",
      "inputs": [
        {
          "param": "amount",
          "source": "$input.amount"
        },
        {
          "param": "currency",
          "source": "$item"
        }
      ]
    },
    {
      "id": "s2",
      "uses": "rank_currency_conversions",
      "foreach": null,
      "inputs": [
        {
          "param": "conversions",
          "source": "$steps.s1.items"
        }
      ]
    }
  ],
  "output_step": "s2",
  "permissions": {
    "net": [
      "www.cnb.cz"
    ],
    "llm": false
  },
  "budget": {
    "max_tokens_per_run": 0
  },
  "lineage": {
    "created_by": "factory",
    "uses": [
      "convert_to_czk_cnb_rate@v1",
      "rank_currency_conversions@v1"
    ]
  },
  "example_input": "{\"currencies\":[\"USD\",\"EUR\",\"GBP\",\"CHF\",\"JPY\"],\"amount\":1}",
  "purpose": "a bot that compares several foreign currencies against the Czech crown today and says which is strongest",
  "version": 1,
  "headline": "Against the Czech crown, {strongest} is the strongest at {ranking.0.czk_per_unit} CZK per unit and {weakest} is the weakest, based on the rate of {rate_date}.",
  "examples": [
    "Which is stronger against the crown, dollar or euro?",
    "Compare GBP, CHF and JPY to CZK today",
    "Rank USD, EUR and PLN against the Czech koruna"
  ],
  "voice": "gremlin",
  "manual_minutes": 8.0,
  "manual_basis": "Look up current CNB exchange rates for 5 currencies, convert 1 unit of each to CZK, rank by resulting values."
}

